let state=load();
let toastTimeout;
const $=s=>document.querySelector(s);
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=n=>Number(n||0).toLocaleString("en-US");
const uid=()=>crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);
const business=id=>state.businesses.find(b=>b.id===id);
const campaign=id=>state.campaigns.find(c=>c.id===id);
const student=id=>state.students.find(s=>s.id===id);
const me=()=>student(state.activeStudent);
const claimsFor=id=>state.claims.filter(x=>x.campaignId===id);
const videoForClaim=id=>state.videos.find(v=>v.claimId===id);
const videosForBusiness=id=>state.videos.filter(v=>campaign(v.campaignId)?.businessId===id);
const videosForMe=()=>state.videos.filter(v=>v.studentId===state.activeStudent);
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE));if(v&&Array.isArray(v.claims)&&Array.isArray(v.videos)&&Array.isArray(v.campaigns)&&Array.isArray(v.students)&&Array.isArray(v.businesses))return {...seed(),...v,tab:"explore",detail:null,friendPreview:false,selectedRestaurant:null,selectedCampaign:null};}catch{}return seed()}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{toast("Browser storage is unavailable; changes may not persist.")}}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove("show"),3200)}
function img(src,alt,extra=""){return '<img src="'+esc(src)+'" alt="'+esc(alt)+'" loading="lazy" '+extra+'>'}
function tag(text,kind=""){return '<span class="status '+kind+'">'+esc(text)+'</span>'}
function btn(label,action,id="",style="button",attrs=""){return '<button type="button" class="'+style+'" data-action="'+esc(action)+'" data-id="'+esc(id)+'" '+attrs+'>'+label+'</button>'}
function nav(){const options=state.role==="student"?[["explore","⌕","Explore"],["visits","▣","My visits"],["content","▥","My content"],["profile","◯","Profile"],["referrals","↗","Refer"]]:[["overview","▦","Overview"],["create","＋","Create offer"],["creators","♧","Creators"],["videos","▣","Creator videos"]];$("#bottomNav").innerHTML=options.map(([id,symbol,label])=>'<button type="button" data-tab="'+id+'" class="'+(state.tab===id?"active":"")+'" aria-current="'+(state.tab===id?"page":"false")+'"><span class="nav-icon">'+symbol+'</span><span>'+label+'</span></button>').join("");$("#roleSwitch").innerHTML=state.role==="student"?'Creator <span>⇄</span>':'Business <span>⇄</span>'}
function heading(kicker,title,sub){return '<p class="eyebrow">'+kicker+'</p><h1 class="page-title">'+title+'</h1>'+(sub?'<p class="subhead">'+sub+'</p>':"")}
function available(c){return Math.max(0,c.spots-claimsFor(c.id).length)}
function capacity(c){return available(c)+' of '+c.spots+' spots left'}
function render(){nav();const screens={explore,visits,content,profile,referrals,overview,create,creators,videos};let html;if(state.detail?.type==="offer")html=offerDetail(state.detail.id);else if(state.detail?.type==="claimed")html=claimedScreen(state.detail.id);else if(state.detail?.type==="friend")html=friendScreen(state.detail.id);else if(state.detail?.type==="restaurant")html=restaurantDetail(state.detail.id);else if(state.detail?.type==="video")html=videoDetail(state.detail.id);else if(state.detail?.type==="campaign")html=campaignResult(state.detail.id);else html=screens[state.tab]();$("#content").innerHTML=html;if(state.tab==="explore"&&state.mapVisible&&!state.detail)requestAnimationFrame(initMap);}
function goTab(tab){state.tab=tab;state.detail=null;render();$("#content").scrollTop=0}
function goDetail(type,id){state.detail={type,id};render();$("#content").scrollTop=0}
function imageTag(c){return c.comp==="cash"?'<span class="image-tag red">COVERED VISIT · '+esc(c.reward)+'</span>':'<span class="image-tag">'+esc(c.reward)+'</span>'}
function offerChips(c){return '<div class="chips"><span class="chip">⌁ '+esc(c.neighborhood)+'</span><span class="chip '+(c.comp==="cash"?"cash":"")+'">'+esc(c.reward)+'</span><span class="chip">'+esc(capacity(c))+'</span></div>'}
function featureCard(c){const b=business(c.businessId);return '<article class="feature-card"><div class="feature-image">'+img(c.image,c.title)+imageTag(c)+'</div><div class="feature-body"><div class="eyeline">'+esc(b.name)+' · '+esc(c.neighborhood)+'</div><h3>'+esc(c.title)+'</h3><p class="card-summary">'+esc(c.description)+'</p>'+offerChips(c)+btn("See the offer ↗","offer",c.id,"button full card-action")+'</div></article>'}
function smallCard(c){const b=business(c.businessId);return '<article class="offer-card"><div class="small-image">'+img(c.image,c.title)+'</div><div class="offer-body"><div class="eyeline">'+esc(c.neighborhood)+' · '+esc(b.name)+'</div><h3>'+esc(c.title)+'</h3><p class="card-summary">'+esc(c.reward)+' · '+esc(capacity(c))+'</p>'+btn("View offer →","offer",c.id,"button text")+'</div></article>'}
function explore(){const featured=campaign("lunch"),others=state.campaigns.filter(c=>c.status==="open"&&c.id!=="lunch");return '<section class="page explore-page">'+heading("YOUR CITY, YOUR CONTENT","Around <em>Providence.</em>","Find your next spot. Make your own video. Enjoy a covered visit.")+'<div class="explore-control"><span class="location">⌖ Providence, RI</span>'+btn(state.mapVisible?"Hide map ↑":"Nearby map ↗","toggle-map","","button secondary tiny")+'</div>'+(state.mapVisible?mapPanel():"")+featureCard(featured)+'<div class="section-heading"><h2>Worth checking out</h2><span>'+others.length+' opportunities</span></div><div class="offers">'+others.map(smallCard).join("")+'</div><div class="notice">Illustrative offers only; named venues have not agreed to participate. Creators post one original video and disclose the covered visit.</div></section>';}
function mapPanel(){return '<section class="map-wrap"><div class="map-frame" id="mapFrame" role="region" aria-label="Nearby creator opportunities"><div class="map-static">⌖ Providence opportunities</div></div><div class="map-key"><span>📍 Providence College area</span><span>Tap a pin or venue below</span></div><div class="map-links">'+state.campaigns.filter(c=>c.status==="open").map(c=>'<button type="button" class="map-link" data-action="offer" data-id="'+esc(c.id)+'">'+esc(business(c.businessId).name)+' <span>View ↗</span></button>').join("")+'</div></section>';}
function initMap(){const host=$("#mapFrame");if(!host)return;if(!window.L){host.innerHTML='<div class="map-static">Map tiles unavailable. Select a venue below.</div>';return;}const map=window.L.map(host,{scrollWheelZoom:false}).setView([41.835,-71.418],13);window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap contributors",maxZoom:19}).addTo(map);state.campaigns.filter(c=>c.status==="open").forEach(c=>{const b=business(c.businessId);if(!Number.isFinite(b.lat)||!Number.isFinite(b.lng))return;const pin=window.L.circleMarker([b.lat,b.lng],{radius:9,color:"#fff",weight:3,fillColor:"#c832ee",fillOpacity:1}).addTo(map);pin.bindTooltip(b.name+" · "+available(c)+" spots");pin.on("click",()=>goDetail("offer",c.id));});window.L.circleMarker([41.8437,-71.4378],{radius:7,color:"#fff",weight:2,fillColor:"#22376e",fillOpacity:1}).bindTooltip("Providence College · reference only").addTo(map);setTimeout(()=>map.invalidateSize(),100);}
function offerDetail(id){const c=campaign(id);if(!c)return explore();const b=business(c.businessId);const my=state.claims.find(x=>x.campaignId===id&&x.studentId===state.activeStudent);const blocked=state.overdueSimulation&&state.claims.some(x=>x.studentId===state.activeStudent&&!videoForClaim(x.id)&&x.status==="overdue");return '<div class="hero-image">'+img(c.image,c.title)+btn("‹","back","","back")+'<span class="pill floating">'+esc(b.name)+' · '+esc(c.neighborhood)+'</span></div><section class="detail-content"><p class="eyebrow">THE OFFER · '+esc(b.name)+'</p><h1 class="page-title">'+esc(c.title)+'</h1>'+offerChips(c)+'<div class="exchange"><strong>'+esc(c.comp==="visit"?"Your visit is covered.":c.reward+" for your post.")+'</strong><p>'+esc(c.comp==="visit"?"Your lunch is covered. Post one original video within 48 hours of your visit.":"Your visit is covered. Post one original video within 48 hours of your visit.")+'</p></div><div class="detail-line"><b>What to try</b><span>'+esc(c.description)+'</span></div><div class="detail-line"><b>Visit window</b><span>'+esc(c.window)+'</span></div><div class="detail-line"><b>Visit by</b><span>'+esc(c.visitBy)+'</span></div><div class="detail-line"><b>Post deadline</b><span>'+esc(c.deadline)+'</span></div><div class="detail-line"><b>Your post</b><span>'+esc(c.post)+'</span></div><div class="detail-group"><h3>Make it your own</h3><p>'+esc(c.brief)+'</p></div><p class="fine-print">Your video goes on your own TikTok or Instagram account. Each creator must post their own video and submit their own link. Be honest and disclose your covered meal or drink.</p><div class="sticky-actions">'+(my?btn("Go to my visit →","visits","","button full"):blocked?'<div class="reminder">Submit your overdue video before claiming another offer.</div>'+btn("Go to my visits","visits","","button full"):available(c)===0?'<button class="button full" disabled>All spots claimed</button>':!me().approved?btn("Apply as a creator first →","profile","","button full"):btn("Claim a spot","claim",id,"button full"))+btn("Back to Explore","back","","button secondary full")+'</div></section>'}
function claim(id,who=state.activeStudent){const c=campaign(id);if(!c||c.status!=="open"||available(c)<=0){toast("There are no spots left.");return null}if(state.claims.some(x=>x.campaignId===id&&x.studentId===who)){toast("This student already has a spot.");return null}const ob={id:uid(),campaignId:id,studentId:who,status:"claimed",review:who==="maya"?"approved":"pending",visitDate:c.visitBy};state.claims.push(ob);persist();return ob}
function claimedScreen(id){const a=state.claims.find(x=>x.id===id);if(!a)return visits();const c=campaign(a.campaignId),b=business(c.businessId);return '<section class="page confirmation"><div class="confirm-art">✳</div><h2>You’re in.<br/>Lunch plans?</h2><p>Your spot at <b>'+esc(b.name)+'</b> is claimed. You can go solo or bring a creator friend.</p><div class="invite"><p class="eyebrow">INVITE A FRIEND</p><h3>Good food is better together.</h3><p>Your friend gets <b>their own spot</b> and must post <b>their own video</b>. Your post and their post are tracked separately.</p><div class="invite-url">fusegenerated.app/invite/'+esc(a.campaignId)+'</div><div class="stack" style="margin-top:12px">'+btn("Preview friend invite →","friend",id,"button dark full")+btn("Copy invite text","copy-invite",id,"button secondary full")+'</div></div><div class="stack">'+btn("Continue solo → My visits","visits","","button full")+'</div><p class="fine-print" style="margin-top:17px">'+esc(capacity(c))+'</p></section>'}
function friendScreen(id){const a=state.claims.find(x=>x.id===id);if(!a)return visits();const c=campaign(a.campaignId),b=business(c.businessId),friend=student("leo"),existing=state.claims.find(x=>x.campaignId===c.id&&x.studentId==="leo");return '<section class="page"><p class="eyebrow">INVITE PREVIEW · '+esc(friend.name)+'</p><div class="feature-image" style="height:195px;border-radius:14px;overflow:hidden">'+img(c.image,c.title)+'</div><div style="padding-top:18px">'+heading("YOU’RE INVITED","Lunch with a friend?","Maya invited you to try "+esc(b.name)+" in "+esc(c.neighborhood)+".")+'</div><div class="panel"><h3>'+esc(c.title)+'</h3>'+offerChips(c)+'<div class="detail-group"><h3>Your own exchange</h3><p>You receive <b>'+esc(c.reward)+'</b> and post <b>one original Reel or TikTok on your own account</b>. Maya’s post does not count as yours.</p></div></div>'+(existing?'<div class="notice green">Leo already accepted this invitation.</div>'+btn("Back to my visits","visits","","button full"):available(c)===0?'<div class="notice">There are no spots left to accept.</div>'+btn("Back","back","","button secondary full"):btn("Accept as Leo →","accept-friend",id,"button full"))+'<p class="fine-print" style="margin-top:12px">Demo friend: Leo Park · Rhode Island College · @leoexplorespvd. Brand may review first-time creators.</p></section>'}
function visits(){const mine=state.claims.filter(x=>x.studentId===state.activeStudent&&campaign(x.campaignId)?.status==="open").reverse();const overdue=mine.filter(a=>a.status==="overdue"&&!videoForClaim(a.id));return '<section class="page">'+heading("YOUR NEXT STOPS","My visits","Every visit, deadline, and video link in one place.")+(overdue.length?'<div class="reminder">⏰ Your post is overdue. Submit your video before claiming another offer.</div>':"")+(mine.length?mine.map(visitCard).join(""):'<div class="empty"><span>⌁</span>No visits yet. Claim a spot on Explore to get started.</div>')+'<div class="section-heading"><h2>Demo controls</h2></div><div class="panel"><p class="small muted">Test a late submission reminder, then submit a link to clear it.</p>'+btn("Simulate overdue post","simulate-overdue","","button secondary full")+'</div></section>'}
function visitCard(a){const c=campaign(a.campaignId),b=business(c.businessId),v=videoForClaim(a.id),pair=claimsFor(c.id),submitted=pair.filter(x=>videoForClaim(x.id)).length;const overdue=a.status==="overdue"&&!v;return '<article class="visit-card"><div class="visit-title"><div><p class="eyeline">'+esc(b.name)+' · '+esc(c.neighborhood)+'</p><h3>'+esc(c.title)+'</h3></div>'+tag(v?"Posted":overdue?"Overdue":a.review==="pending"?"Awaiting review":"Claimed",v?"good":overdue?"late":a.review==="pending"?"waiting":"new")+'</div><div class="detail-line"><b>Visit by</b><span>'+esc(c.visitBy)+' · '+esc(c.window)+'</span></div><div class="detail-line"><b>Post by</b><span>'+esc(c.deadline)+'</span></div><div class="progress-track"><i style="width:'+Math.round(100*submitted/Math.max(1,pair.length))+'%"></i></div><p class="tiny-muted">'+submitted+' of '+pair.length+' posts submitted for this visit</p>'+(pair.length>1?'<p class="small muted">Creators: '+pair.map(x=>esc(student(x.studentId)?.name||"Student")+(videoForClaim(x.id)?" ✓":" · pending")).join(" · ")+'</p>':"")+(v?'<div class="notice green">✓ Your video is submitted. '+(v.demo?"Demo analytics":"Stats pending")+'.</div>'+btn("See my content →","content","","button secondary full"):a.review==="pending"?'<div class="notice">The restaurant can review your creator profile. Your spot is held during this demo.</div>'+submitForm(a):((a.status==="claimed"?btn("Mark visit complete","mark-visited",a.id,"button secondary full"):"") +submitForm(a)))+'<p class="fine-print">Only your own post satisfies your commitment. Include a clear disclosure.</p></article>'}
function submitForm(a){return '<form data-form="post" data-id="'+esc(a.id)+'"><div class="form-group"><label class="label" for="post-'+esc(a.id)+'">Paste your TikTok or Instagram Reel link</label><input id="post-'+esc(a.id)+'" class="field" name="url" type="url" required placeholder="https://www.tiktok.com/@you/video/..." /></div><button class="button full" type="submit">Submit my video →</button></form>'}
function content(){const groups=state.businesses.map(b=>({b,posts:videosForMe().filter(v=>campaign(v.campaignId)?.businessId===b.id)})).filter(g=>g.posts.length);return '<section class="page">'+heading("YOUR CREATOR PORTFOLIO","My content","What have I posted for each restaurant, and how did those videos do?")+'<div class="metric-row"><div class="metric-panel"><strong>'+videosForMe().length+'</strong><span>Published videos</span></div><div class="metric-panel"><strong>'+fmt(videosForMe().reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Total reported video views</span></div></div>'+(groups.length?groups.map(g=>restaurantCard(g.b,g.posts)).join(""):'<div class="empty"><span>▥</span>Your first submitted video will show up here.</div>')+'<div class="notice">Seeded analytics are demo data, last updated Nov 10, 2026. New submissions show “Stats pending.” Your totals exclude friends’ videos.</div></section>'}
function restaurantCard(b,posts){return '<article class="restaurant-card"><div class="restaurant-photo">'+img(b.photo,b.name)+'</div><div style="min-width:0;flex:1"><p class="eyeline">'+esc(b.neighborhood)+'</p><h3>'+esc(b.name)+'</h3><p class="tiny-muted">'+posts.length+' published post'+(posts.length===1?"":"s")+' · '+fmt(posts.reduce((sum,v)=>sum+(v.views||0),0))+' views</p>'+btn("View my videos →","restaurant",b.id,"button text")+'</div></article>'}
function restaurantDetail(id){const b=business(id),posts=videosForMe().filter(v=>campaign(v.campaignId)?.businessId===id).reverse();return '<section class="page">'+btn("← My content","content","","button text")+heading("MY RESTAURANT HISTORY",esc(b.name),esc(b.neighborhood)+" · "+posts.length+" of my published videos across "+new Set(posts.map(p=>p.campaignId)).size+" campaigns.")+'<div class="metric-row"><div class="metric-panel"><strong>'+posts.length+'</strong><span>My posts</span></div><div class="metric-panel"><strong>'+fmt(posts.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>My total views</span></div></div>'+posts.map(v=>videoCard(v,false)).join("")+'<div class="notice">My statistics include only my own posts. Demo analytics last updated Nov 10, 2026; new posts show Stats pending.</div></section>'}
function videoCard(v,showCreator=false){const c=campaign(v.campaignId),s=student(v.studentId),pending=v.views===null;return '<article class="video-card"><div class="flex align-start"><div class="video-thumb">'+img(v.image,v.title)+'<span class="play">▶</span></div><div style="min-width:0;flex:1"><p class="eyeline">'+esc(v.platform)+' · '+esc(v.date)+'</p><h4>'+esc(v.title)+'</h4>'+(showCreator?'<p class="tiny-muted">By '+esc(s?.name||"Creator")+' · '+esc(s?.handle||"")+'</p>':"")+'<div class="stats-list">'+(pending?'<span>Stats pending</span>':'<span>▶ '+fmt(v.views)+' views</span><span>♥ '+fmt(v.likes)+'</span><span>☷ '+fmt(v.comments)+'</span><span>◇ '+fmt(v.saves)+'</span>')+'</div>'+btn("View video →","video",v.id,"button text")+'</div></div><p class="brief"><b>Campaign:</b> '+esc(c.title)+' · '+esc(c.brief)+'</p><p class="tiny-muted">'+(v.demo?"Demo data · Stats last updated "+esc(v.updated):"Newly submitted · Stats pending")+'</p></article>'}
function videoDetail(id){const v=state.videos.find(v=>v.id===id);if(!v)return content();const c=campaign(v.campaignId),s=student(v.studentId);return '<section class="page">'+btn("← Back","back","","button text")+heading("PUBLISHED VIDEO",esc(v.title),esc(s.name)+" · "+esc(v.platform)+" · "+esc(v.date))+'<div class="video-preview">'+img(v.image,v.title)+'<div class="play">▶</div></div><p class="preview-caption">Thumbnail preview only. The original video opens on '+esc(v.platform)+'. For the hackathon, seeded video URLs are sample platform links.</p><div class="metric-row">'+[["Views",v.views],["Likes",v.likes],["Comments",v.comments],["Saves",v.saves]].map(([k,val])=>'<div class="metric-panel"><strong>'+(val===null?"—":fmt(val))+'</strong><span>'+k+'</span></div>').join("")+'</div><div class="panel"><p class="eyeline">CAMPAIGN BRIEF</p><h3>'+esc(c.title)+'</h3><p class="small muted">'+esc(c.brief)+'</p></div><a class="button full" target="_blank" rel="noopener noreferrer" href="'+esc(v.url)+'">Open original post ↗</a><p class="fine-print" style="margin-top:13px">'+(v.demo?"Sample analytics are demo data · Last updated "+esc(v.updated):"Stats pending. Analytics are not automatically fetched from TikTok or Instagram.")+'</p></section>'}
function profile(){const u=me();return '<section class="page">'+heading("YOUR CREATOR CARD","Your profile","Make good local videos. No follower minimum.")+'<div class="panel"><h3>'+esc(u.name)+'</h3><p class="small muted">'+esc(u.school)+' · '+esc(u.handle)+'</p>'+tag(u.approved?"Approved creator":"Pending review",u.approved?"good":"waiting")+'<p class="small muted">'+esc(u.history)+'</p>'+btn("Edit my profile","edit-profile","","button secondary full")+'<div style="margin-top:10px">'+btn("Switch demo creator →","switch-student","","button secondary full")+'</div></div><div class="panel"><h3>Bring your friends.</h3><p class="small muted">Invite other Providence creators and see your referral activity.</p>'+btn("Open referral program →","referrals","","button full")+'</div><p class="fine-print">Anyone can apply with local post examples. FuseGenerated is independent of Providence College.</p></section>';}
function referrals(){const n=state.referrals.length;return '<section class="page">'+heading("SHARE YOUR CITY","Refer a friend.","Invite local creators and discover more places together.")+'<div class="referral-hero"><p class="eyebrow">YOUR REFERRAL CODE</p><h2>'+esc(state.referralCode)+'</h2><p>Share your unique demo code with a friend.</p>'+btn("Copy invite","copy-referral","","button full")+'</div><div class="metric-row"><div class="metric-panel"><strong>'+n+'</strong><span>Friends joined · demo</span></div><div class="metric-panel"><strong>'+Math.min(n,2)+'/2</strong><span>Toward early access</span></div></div><div class="panel"><h3>How it works</h3><p class="small muted">Share your code. A friend joins with their own account. Two verified referrals will unlock early previews of new offers when the pilot launches.</p>'+btn("Preview friend joining →","referral-join","","button secondary full")+'</div><div class="notice">Referral tracking and rewards are demo-only. No real invite is sent.</div></section>';}
function overview(){const active=state.campaigns.filter(c=>c.status==="open"),videos=videosForBusiness("juniper"),total=state.claims.filter(c=>campaign(c.campaignId)?.businessId==="juniper").length;return '<section class="page">'+heading("FOR THE PLACES WE LOVE","Business overview","A simple view of the content your restaurant actually receives.")+'<div class="role-info">Demo owner: <b>Juniper & Rye</b>, Elmhurst · Fictional café</div><div class="metric-row"><div class="metric-panel"><strong>'+total+'</strong><span>Total creator claims · Juniper & Rye</span></div><div class="metric-panel"><strong>'+videos.length+'</strong><span>Videos submitted · Juniper & Rye</span></div></div><div class="section-heading"><h2>Campaign results</h2><span>Tap to inspect</span></div>'+state.campaigns.filter(c=>c.businessId==="juniper").map(resultCard).join("")+'<div class="section-heading"><h2>What the pilot costs</h2></div><div class="panel"><h3>$0 to use FuseGenerated.</h3><p class="small muted">There is no platform fee during this pilot. Your only cost is the food and drink you offer to up to three approved creators. Each creates and shares an original, disclosed video on their own account.</p><p class="small muted">Approve the creator, check their visit claim at the counter, cover their agreed order, and track their submitted video in your dashboard.</p></div><div class="section-heading"><h2>Bring people in</h2></div><div class="panel"><h3>One offer. A few local voices.</h3><p class="small muted">Run a free pilot with up to three covered visits. Your only cost is the promised food and drinks.</p>'+btn("+ Create another offer","create","","button full")+'</div><div class="notice">Your deliverable is the agreed creator posts—not guaranteed customers or search rankings. Views and owner-reported customer visits are tracked separately.</div></section>'}
function resultCard(c){const claims=claimsFor(c.id),posted=claims.filter(x=>videoForClaim(x.id)),visits=state.customerVisits[c.id]||0;return '<article class="result-card"><div class="flex between"><span class="eyeline">'+esc(c.title)+'</span>'+tag(c.status==="completed"?"Completed":"Open",c.status==="completed"?"good":"waiting")+'</div><h3 class="result-title">'+esc(business(c.businessId).name)+'</h3><div class="counts"><div><strong>'+claims.length+'</strong>claimed</div><div><strong>'+claims.filter(x=>x.status==="visited"||x.status==="posted").length+'</strong>visited</div><div><strong>'+posted.length+'</strong>posted</div><div><strong>'+visits+'</strong>reported visits</div></div><div style="margin-top:14px">'+btn("See campaign results →","campaign",c.id,"button secondary full")+'</div></article>'}
function campaignResult(id){const c=campaign(id),b=business(c.businessId),cl=claimsFor(id),vs=state.videos.filter(v=>v.campaignId===id),reported=state.customerVisits[id]||0;return '<section class="page">'+btn("← Business overview","overview","","button text")+heading("CAMPAIGN RESULTS",esc(c.title),esc(b.name)+" · "+esc(c.neighborhood))+'<div class="metric-row"><div class="metric-panel"><strong>'+cl.length+' / '+c.spots+'</strong><span>Creator spots claimed</span></div><div class="metric-panel"><strong>'+vs.length+'</strong><span>Individual posts submitted</span></div><div class="metric-panel"><strong>'+fmt(vs.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Video views · demo analytics</span></div><div class="metric-panel"><strong>'+reported+'</strong><span>Customer visits reported by you</span></div></div><div class="report-box"><strong>A customer showed us a post</strong><p>Customer visits reported by you · not verified by FuseGenerated</p>'+btn("+1 customer visit","plus-one",id,"button dark tiny")+'</div><div class="section-heading"><h2>Creator follow-through</h2></div>'+(cl.length?cl.map(a=>'<div class="panel"><div class="flex between"><div><b>'+esc(student(a.studentId)?.name||"Student")+'</b><p class="tiny-muted">'+esc(student(a.studentId)?.handle||"")+'</p></div>'+tag(videoForClaim(a.id)?"Posted":a.status==="visited"?"Visited":a.review==="pending"?"Needs review":"Claimed",videoForClaim(a.id)?"good":"waiting")+'</div>'+(videoForClaim(a.id)?btn("Watch / open video →","video",videoForClaim(a.id).id,"button text"):'<p class="small muted">Post still due · '+esc(c.deadline)+'</p>')+'</div>').join(""):'<div class="empty">No creators have claimed this offer yet.</div>')+'<div class="section-heading"><h2>Submitted videos</h2></div>'+(vs.length?'<div class="panel">'+vs.map(v=>videoCard(v,true)).join("")+'</div>':'<div class="empty">Published videos will appear here as links are submitted.</div>')+'<div class="notice">Video views, likes, comments, and saves are seeded demo data when shown; new links display Stats pending. No guaranteed visits or rankings.</div></section>'}
function create(){return '<section class="page">'+heading("QUICK CAMPAIGN BUILDER","Create an offer","A café owner should be able to finish this between customers.")+'<form data-form="new-offer"><div class="form-group"><label class="label" for="discover">What do you want people in Providence to discover?</label><input class="field" id="discover" name="title" placeholder="Our weekday lunch special" required maxlength="100"></div><div class="form-group"><label class="label" for="businessName">Business name</label><input class="field" id="businessName" name="business" value="Juniper & Rye" required maxlength="85"></div><div class="form-group"><label class="label" for="neighborhood">Neighborhood</label><select class="field" id="neighborhood" name="neighborhood"><option>Elmhurst</option><option>Federal Hill</option><option>College Hill</option><option>Downtown</option><option>Fox Point</option><option>Wayland Square</option></select></div><div class="form-group"><label class="label" for="offer">What does the creator get?</label><input class="field" id="offer" name="reward" placeholder="Lunch for one, up to $15" required maxlength="85"></div><div class="form-group"><label class="label">What is covered for each creator?</label><div class="toggle-pair"><button type="button" class="choice '+(state.offerComp==="visit"?"selected":"")+'" data-action="set-comp" data-id="visit">✳ Cover the visit</button><button type="button" class="choice '+(state.offerComp==="cash"?"selected":"")+'" data-action="set-comp" data-id="visit">☕ Cover food & drink</button></div></div><div class="form-row"><div class="form-group"><label class="label" for="spots">Creator spots</label><input class="field" id="spots" name="spots" type="number" min="3" max="3" value="3" readonly required></div><div class="form-group"><label class="label" for="window">Visit window</label><input class="field" id="window" name="window" value="Weekdays 11 AM–2 PM" required maxlength="80"></div></div><div class="form-group"><label class="label" for="post">What should they post?</label><textarea class="field" id="post" name="post" required maxlength="250">One original TikTok or Reel on their own account within 48 hours of visiting.</textarea></div><div class="notice">Creators keep their own voice and disclose covered visits. Free pilot: $0 platform fee. Your business covers only the food and drinks promised to three creators. No subscription, listing fee or per-video platform fee.</div><button class="button full" type="submit">Publish demo offer →</button></form></section>'}
function creators(){const at=state.claims.filter(a=>a.review==="pending"||a.review==="approved").slice().reverse();const creatorIds=["maya","leo"];return '<section class="page">'+heading("WHO’S MAKING THE VIDEOS?","Review creators","See examples of local work and whether each creator follows through.")+'<div class="notice">Approving a creator updates this interactive demo only. No real messages are sent.</div>'+creatorIds.map(id=>creatorReview(student(id))).join("")+'<div class="section-heading"><h2>Current claims</h2></div>'+(at.length?at.map(a=>{const s=student(a.studentId),c=campaign(a.campaignId);return '<div class="panel"><div class="flex between"><div><b>'+esc(s.name)+'</b><p class="tiny-muted">'+esc(c.title)+'</p></div>'+tag(a.review==="approved"?"Approved":"Needs approval",a.review==="approved"?"good":"waiting")+'</div>'+(a.review!=="approved"?btn("Approve creator","approve",a.id,"button tiny"):btn("View campaign →","campaign",c.id,"button text"))+'</div>'}).join(""):'<div class="empty">New student claims will appear here.</div>')+'</section>'}
function creatorReview(s){const p1=s.id==="maya"?PHOTO.coffee:PHOTO.city,p2=s.id==="maya"?PHOTO.toast:PHOTO.bowl;return '<article class="creator-card"><div class="flex between"><div><h3>'+esc(s.name)+'</h3><p class="small muted">'+esc(s.school)+' · '+esc(s.handle)+'</p></div>'+tag(s.history,s.id==="maya"?"good":"new")+'</div><div class="preview-row">'+img(p1,"Local content example one")+img(p2,"Local content example two")+'</div><div class="flex between"><span class="tiny-muted">Two local content previews · sample images</span>'+btn("Open samples ↗","samples",s.id,"button text")+'</div>'+(s.id==="leo"?'<div class="notice">First visit · review their local video samples, not follower counts.</div>':"")+'</article>'}
function videos(){const b=business("juniper"),campaigns=state.campaigns.filter(c=>c.businessId==="juniper"),total=videosForBusiness("juniper");return '<section class="page">'+heading("JUNIPER & RYE","Creator videos","Every video submitted for your restaurant, grouped by campaign.")+'<div class="metric-row"><div class="metric-panel"><strong>'+total.length+'</strong><span>Videos submitted</span></div><div class="metric-panel"><strong>'+fmt(total.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Demo video views</span></div></div>'+campaigns.map(c=>{const posts=state.videos.filter(v=>v.campaignId===c.id);return '<div class="section-heading"><h2 style="font-size:19px">'+esc(c.title)+'</h2><span>'+posts.length+' posts</span></div>'+(posts.length?'<div class="panel">'+posts.map(v=>videoCard(v,true)).join("")+'</div>':'<div class="empty">No submissions for this offer yet.</div>')}).join("")+'<div class="notice">Seeded analytics are demo data, last updated Nov 10, 2026. Newly submitted videos say Stats pending. Restaurant-reported customer visits are tracked on campaign results, not added to video views.</div></section>'}
function formModal(title,body,submit,handler){$("#modalTitle").textContent=title;$("#modalContent").innerHTML='<form id="dialogForm">'+body+'<button type="submit" class="button full">'+submit+'</button></form>';$("#modal").showModal();$("#dialogForm").addEventListener("submit",e=>{e.preventDefault();handler(new FormData(e.currentTarget))})}
function closeModal(){$("#modal").close()}
function userJoin(){const s=me();formModal("Join as a creator",'<p class="small muted">Anyone can apply. No minimum followers. Two helpful local posts, or a starter sample.</p>'+field("school","Your school",s.school)+field("handle","Social handle",s.handle)+field("post1","Local post link #1",s.links[0]||"","url")+field("post2","Local post link #2",s.links[1]||"","url")+'<p class="help">New creators can join without a follower minimum. Add two useful local post links for review.</p>',"Save application",data=>{const school=String(data.get("school")||"").trim(),handle=String(data.get("handle")||"").trim(),links=["post1","post2"].map(k=>String(data.get(k)||"").trim());if(!school||!handle){toast("Add your school and handle.");return}if(links.some(x=>x&&!validUrl(x))){toast("Enter valid http(s) post links.");return}s.school=school;s.handle=handle;s.links=links.filter(Boolean);if(s.links.length<2){toast("Saved. Add two posts or complete the starter brief for review.");}else toast("Creator application saved for review.");persist();closeModal();render()})}
function editProfile(){const s=me();formModal("Your creator profile",field("name","Name",s.name)+field("school","School",s.school)+field("handle","Social handle",s.handle),"Save profile",d=>{const name=String(d.get("name")||"").trim(),school=String(d.get("school")||"").trim(),handle=String(d.get("handle")||"").trim();if(!name||!school||!handle)return toast("Complete all fields.");Object.assign(s,{name,school,handle});persist();closeModal();render();toast("Profile updated.")})}
function starter(){formModal("Starter brief",'<p class="tagline">“Where would you send a friend for lunch under $15 in Providence?”</p><p class="small muted">Share a useful sample that names a location, approximate price, and what you actually recommend.</p>'+field("link","Your sample video link","","url"),"Submit sample",d=>{const link=String(d.get("link")||"").trim();if(!validUrl(link))return toast("Enter a valid public video URL.");state.starterStatus="submitted";persist();closeModal();render();toast("Starter sample submitted for demo review.")})}
function field(name,label,value="",type="text"){return '<div class="form-group"><label class="label" for="field-'+name+'">'+label+'</label><input class="field" id="field-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" required maxlength="250"></div>'}
function validUrl(url){try{const u=new URL(url);return (u.protocol==="https:"||u.protocol==="http:")&&!!u.hostname.includes(".")}catch{return false}}
function validSocialLink(url){if(!validUrl(url))return false;const host=new URL(url).hostname.toLowerCase();return host==="tiktok.com"||host.endsWith(".tiktok.com")||host==="instagram.com"||host.endsWith(".instagram.com")}
function submitPost(id,data){const a=state.claims.find(x=>x.id===id);if(!a||a.studentId!==state.activeStudent||videoForClaim(id))return toast("This visit is already submitted.");const url=String(data.get("url")||"").trim();if(!validSocialLink(url))return toast("Use a public TikTok or Instagram URL.");const host=new URL(url).hostname.toLowerCase(),plat=host.includes("tiktok")?"TikTok":"Instagram Reel",c=campaign(a.campaignId);state.videos.push({id:uid(),claimId:id,studentId:state.activeStudent,campaignId:c.id,url,title:c.title+" · "+me().name,platform:plat,date:new Date().toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}),image:c.image,views:null,likes:null,comments:null,saves:null,updated:null,demo:false});a.status="posted";state.overdueSimulation=false;persist();goTab("content");toast("Posted! Your video is now in your portfolio and the restaurant dashboard.")}
function createOffer(data){const title=String(data.get("title")||"").trim(),name=String(data.get("business")||"").trim(),neighborhood=String(data.get("neighborhood")||"Elmhurst").trim(),reward=String(data.get("reward")||"").trim(),window=String(data.get("window")||"").trim(),post=String(data.get("post")||"").trim(),spots=Number(data.get("spots"));if(!title||!name||!reward||!window||!post||!Number.isInteger(spots)||spots!==3)return toast("Please complete the offer details.");let b=state.businesses.find(x=>x.name.toLowerCase()===name.toLowerCase());if(!b){b={id:uid(),name,neighborhood,photo:PHOTO.lunch};state.businesses.push(b)}const c={id:uid(),businessId:b.id,title,neighborhood,comp:"visit",reward,spots,window,deadline:"Within 48 hours of your visit",post,brief:"Show what you ordered, what it costs, and why your friends should know about this place. Share your honest take and disclose your compensation.",description:"A new local opportunity created for the FuseGenerated demo.",image:PHOTO.lunch,price:reward,status:"open",visitBy:"Dec 15, 2026"};state.campaigns.unshift(c);state.customerVisits[c.id]=0;state.offerComp="visit";persist();goTab("overview");goDetail("campaign",c.id);toast("Demo offer published! Switch to Student to claim it.")}
function showSamples(id){const s=student(id);$("#modalTitle").textContent=s.name+" · local samples";$("#modalContent").innerHTML='<div class="stack"><div class="video-preview" style="height:170px">'+img(id==="maya"?PHOTO.coffee:PHOTO.city,"Local preview")+'</div><p class="small muted">Sample local post 1 · '+esc(s.handle)+'</p><div class="video-preview" style="height:170px">'+img(id==="maya"?PHOTO.toast:PHOTO.bowl,"Local preview")+'</div><p class="small muted">Sample local post 2 · '+esc(s.handle)+'</p><p class="fine-print">Photo previews are illustrative demo placeholders; real uploaded creator posts are not fetched.</p></div>';$("#modal").showModal()}
function copyInvite(id){const a=state.claims.find(x=>x.id===id),c=campaign(a.campaignId);const msg="I claimed a FuseGenerated spot for "+c.title+" at "+business(c.businessId).name+". Want to come? Your own spot is covered, and you post your own original video. Demo invite: fusegenerated.app/invite/"+c.id;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(msg).then(()=>toast("Invite text copied.")).catch(()=>toast(msg));else toast("Invite preview available below.");}
function doAction(action,id){switch(action){
case"toggle-map":state.mapVisible=!state.mapVisible;render();return;
case"copy-referral":{const copy="Join FuseGenerated for covered Providence creator visits! My demo code: "+state.referralCode;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(copy).then(()=>toast("Invite copied")).catch(()=>toast(copy));else toast(copy);return;}
case"referral-join":if(!state.referrals.includes("leo")){state.referrals.push("leo");persist();toast("Leo joined your demo invite.");}else toast("Already joined in demo.");render();return;
case"switch-student":state.activeStudent=state.activeStudent==="maya"?"leo":"maya";persist();render();return toast("Now previewing "+me().name);
case"offer":return goDetail("offer",id);
case"back":if(state.detail?.type==="offer")return goTab("explore");if(state.detail?.type==="friend")return goDetail("claimed",id);if(state.detail?.type==="claimed")return goTab("visits");if(state.detail?.type==="restaurant")return goTab("content");if(state.detail?.type==="video")return goTab(state.role==="student"?"content":"videos");return goTab(state.role==="student"?"explore":"overview");
case"claim":{const a=claim(id);if(a)goDetail("claimed",a.id);return}
case"friend":return goDetail("friend",id);
case"accept-friend":{const original=state.claims.find(x=>x.id===id);if(!original)return;const a=claim(original.campaignId,"leo");if(!a)return;state.activeStudent="leo";persist();goTab("visits");toast("Leo accepted. Both spots are now claimed.");return}
case"copy-invite":return copyInvite(id);
case"visits":case"explore":case"content":case"profile":case"referrals":case"overview":case"create":case"creators":case"videos":return goTab(action);
case"restaurant":return goDetail("restaurant",id);
case"video":return goDetail("video",id);
case"campaign":return goDetail("campaign",id);
case"plus-one":state.customerVisits[id]=(state.customerVisits[id]||0)+1;persist();render();return toast("Customer visit reported.");
case"set-comp":state.offerComp=id;document.querySelectorAll(".choice").forEach(b=>b.classList.toggle("selected",b.dataset.id===id));return;
case"switch-student":state.activeStudent=state.activeStudent==="maya"?"leo":"maya";persist();render();return toast("Now demoing as "+me().name+".");
case"join":return userJoin();
case"edit-profile":return editProfile();
case"starter":return starter();
case"samples":return showSamples(id);
case"approve":{const a=state.claims.find(x=>x.id===id);if(!a)return;a.review="approved";student(a.studentId).approved=true;persist();render();return toast("Creator approved for this demo.")}
case"mark-visited":{const a=state.claims.find(x=>x.id===id);if(a&&a.studentId===state.activeStudent&&!videoForClaim(id)){a.status="visited";persist();render();toast("Visit marked complete. Don't forget your video.");}return;}
case"simulate-overdue":{let a=state.claims.find(x=>x.studentId===state.activeStudent&&campaign(x.campaignId)?.status==="open"&&!videoForClaim(x.id));if(!a)return toast("Claim a new offer first to test the overdue reminder.");a.status="overdue";state.overdueSimulation=true;persist();render();return toast("Overdue reminder activated. New claims are blocked until posting.")}
}}
document.addEventListener("click",e=>{const a=e.target.closest("[data-action],[data-tab]");if(!a)return;if(a.dataset.tab)return goTab(a.dataset.tab);if(a.dataset.action)doAction(a.dataset.action,a.dataset.id)});
document.addEventListener("submit",e=>{const form=e.target.closest("[data-form]");if(!form)return;e.preventDefault();if(form.dataset.form==="post")submitPost(form.dataset.id,new FormData(form));if(form.dataset.form==="new-offer")createOffer(new FormData(form))});
$("#roleSwitch").addEventListener("click",()=>{state.role=state.role==="student"?"business":"student";state.detail=null;state.tab=state.role==="student"?"explore":"overview";persist();render();$("#content").scrollTop=0});
$("#resetDemo").addEventListener("click",()=>{if(!confirm("Reset all demo claims, submissions, and offers?"))return;state=seed();persist();render();$("#content").scrollTop=0;toast("Demo reset to the starting state.")});
$("#closeModal").addEventListener("click",closeModal);
$("#modal").addEventListener("click",e=>{if(e.target===$("#modal"))closeModal()});
render();
